import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:unbound_mobile/domain/amount.dart';
import 'package:unbound_mobile/domain/approval_guard.dart';
import 'package:unbound_mobile/domain/models.dart';
import 'package:unbound_mobile/integrations/xdr_inspector.dart';

/// Fixtures are generated by unbound-stellar's REAL transaction builders (SimulatedLedger accounts,
/// synthetic keys) and copied from that repo: test/fixtures/transactions.v1.json.
Map<String, Object?> load() =>
    jsonDecode(File('test/fixtures/transactions.v1.json').readAsStringSync()) as Map<String, Object?>;

void main() {
  const inspector = StellarXdrInspector();
  final f = load();
  final accounts = f['accounts']! as Map<String, Object?>;
  final user = accounts['user']! as String;
  final issuer = accounts['issuer']! as String;
  final target = accounts['targetIssuer']! as String;
  final settlement = f['settlement']! as Map<String, Object?>;
  final quote = Quote.fromJson(f['quote']! as Map<String, Object?>);

  test('decodes the real settlement XDR and reproduces the producer\'s tx hash', () {
    final s = inspector.inspect(settlement['xdr']! as String);
    expect(s.hash, settlement['hash']);
    expect(s.operationType, 'pathPaymentStrictSend');
    expect(s.sourceAccount, user);
    expect(s.destination, user);
    expect(s.sendAsset, AssetRef('SHOP', issuer));
    expect(s.destAsset, AssetRef('USDC', target));
    expect(s.sendAmount, Amount.parse('80'));
    expect(s.destMin, Amount.parse('71.28'));
    expect(s.path, isEmpty);
    expect(s.operationCount, 1);
  });

  test('signing does not change the hash the inspector reports', () {
    expect(inspector.inspect(settlement['signedXdr']! as String).hash, settlement['hash']);
  });

  test('decodes the real redemption-return XDR (payment back to the issuer)', () {
    final r = f['redemptionReturn']! as Map<String, Object?>;
    final s = inspector.inspect(r['xdr']! as String);
    expect(s.operationType, 'payment');
    expect(s.destination, issuer);
    expect(s.sendAmount, Amount.parse('30'));
    expect(s.hash, r['hash']);
  });

  test('ApprovalGuard accepts the REAL settlement against the REAL quote', () {
    final intent = IntentView(
      id: 'int_1',
      state: IntentState.awaitingSignature,
      quoteId: quote.quoteId,
      txHash: settlement['hash']! as String,
      unsignedXdr: settlement['xdr']! as String,
      failureReason: null,
      amountOutActual: null,
      ledger: null,
    );
    final ok = const ApprovalGuard(inspector).check(
      quote: quote,
      intent: intent,
      ownAccounts: {user},
      signingAccount: user,
      now: quote.issuedAt,
    );
    expect(ok.expectedHash, settlement['hash']);
  });

  test('ApprovalGuard refuses real XDR when the account is not ours or the advertised hash lies', () {
    IntentView intent(String hash) => IntentView(
          id: 'i',
          state: IntentState.awaitingSignature,
          quoteId: quote.quoteId,
          txHash: hash,
          unsignedXdr: settlement['xdr']! as String,
          failureReason: null,
          amountOutActual: null,
          ledger: null,
        );
    expect(
      () => const ApprovalGuard(inspector).check(quote: quote, intent: intent(settlement['hash']! as String), ownAccounts: {'GSOMEONEELSE'}, signingAccount: user, now: quote.issuedAt),
      throwsA(isA<ApprovalRefused>().having((e) => e.reasons, 'reasons', contains(RefusalReason.foreignDestination))),
    );
    expect(
      () => const ApprovalGuard(inspector).check(quote: quote, intent: intent('f' * 64), ownAccounts: {user}, signingAccount: user, now: quote.issuedAt),
      throwsA(isA<ApprovalRefused>().having((e) => e.reasons, 'reasons', contains(RefusalReason.hashMismatch))),
    );
  });

  test('a tampered quote (lower floor) no longer matches the real XDR', () {
    final json = Map<String, Object?>.from(f['quote']! as Map<String, Object?>)..['minDestinationAmount'] = '1.0000000';
    final tampered = Quote.fromJson(json);
    final intent = IntentView(
      id: 'i',
      state: IntentState.awaitingSignature,
      quoteId: tampered.quoteId,
      txHash: settlement['hash']! as String,
      unsignedXdr: settlement['xdr']! as String,
      failureReason: null,
      amountOutActual: null,
      ledger: null,
    );
    expect(
      () => const ApprovalGuard(inspector).check(quote: tampered, intent: intent, ownAccounts: {user}, signingAccount: user, now: tampered.issuedAt),
      throwsA(isA<ApprovalRefused>().having((e) => e.reasons, 'reasons', contains(RefusalReason.floorMismatch))),
    );
  });

  test('refuses garbage, truncated and non-transaction input', () {
    for (final bad in ['', 'not base64!!', 'AAAA', (settlement['xdr']! as String).substring(0, 40)]) {
      expect(() => inspector.inspect(bad), throwsA(anything), reason: bad);
    }
  });
}
